def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    sequence = list(map(int, data[1:]))

    # Memoization table to store the maximum value we can achieve from a subarray
    memo = {}

    # Function to calculate the maximum value from subarray l to r
    def max_value(l, r):
        if l == r:
            return sequence[l]
        if (l, r) in memo:
            return memo[(l, r)]

        # If we choose the leftmost element
        if l + 1 <= r:
            left_choice = sequence[l] + max_value(l + 1, r)
        else:
            left_choice = float('-inf')

        # If we choose the rightmost element
        if l <= r - 1:
            right_choice = sequence[r] + max_value(l, r - 1)
        else:
            right_choice = float('-inf')

        # If we choose an internal element
        max_internal = float('-inf')
        if l + 1 < r:
            for i in range(l + 1, r):
                internal_choice = sequence[i - 1] + sequence[i + 1] + max_value(l, i - 1) + max_value(i + 1, r)
                max_internal = max(max_internal, internal_choice)

        # The best choice is the maximum of the three options
        best_choice = max(left_choice, right_choice, max_internal)
        memo[(l, r)] = best_choice
        return best_choice

    # Calculate the maximum value for the entire sequence
    max_possible_value = max_value(0, N - 1)

    # Reconstruct the sequence to find the operations
    operations = []
    l, r = 0, N - 1

    while l < r:
        if sequence[l] + max_value(l + 1, r) == max_value(l, r):
            operations.append(l + 1)
            l += 1
        elif sequence[r] + max_value(l, r - 1) == max_value(l, r):
            operations.append(r + 1)
            r -= 1
        else:
            for i in range(l + 1, r):
                if sequence[i - 1] + sequence[i + 1] + max_value(l, i - 1) + max_value(i + 1, r) == max_value(l, r):
                    operations.append(i + 1)
                    l, r = l, i - 1
                    break

    # Output the results
    print(max_possible_value)
    print(len(operations))
    for op in operations:
        print(op)

